  dm('quad', 'white', 3.4, 2.35, 7.5, 0.45, -Math.PI * 0.5, 0.42, 1.4, 5.4, 1, { tint: [0.98, 0.74, 0.25, 0.15], emissive: 1.0 });
  dm('quad', 'white', 0.0, 2.45, 22.0, -0.52, 0, 0, 1.9, 4.4, 1, { tint: [0.55, 0.85, 1.0, 0.12 + st.maryHalo * 0.15], emissive: 1.0 });

