  drawPoly3D(ctx, cam, [[-5.5, 0.45, 24.4], [5.5, 0.45, 24.4], [5.5, 7.8, 24.4], [-5.5, 7.8, 24.4]], '#D2BC9E', '#5A251B', 1);

