  dm('box', 'yinYangRoof', 0.0, 4.02, 0.0, 0, 0, 0, 2.9, 0.36, 0.8, { tint: [1,1,1,1], us: 2, vs: 1 });
  dm('quad', 'tamQuanSign', 0.0, 3.05, 0.18, 0, 0, 0, 3.2, 0.72, 1, { tint: [1,1,1,1] });
