  dm('cyl', 'darkTimber', 3.68, 1.15, 6.62, 0, 0, 0.08, 0.12, 1.65, 0.12, { tint: [0.75, 0.62, 0.48, 1] });
  dm('cyl', 'darkTimber', 4.62, 1.18, 7.05, 0, 0, -0.08, 0.12, 1.70, 0.12, { tint: [0.75, 0.62, 0.48, 1] });
  var bSway = Math.sin(t * 1.4) * 0.04;
