    g.fillStyle = '#F4B93B'; g.fillRect(6, 0, 10, 256); g.fillRect(240, 0, 10, 256);
    g.fillStyle = '#FDE047'; g.fillRect(24, 0, 4, 256); g.fillRect(228, 0, 4, 256);
    wgl.registerTextureCanvas('redCarpet', c, true);
