  dm('box', 'lockerWall', 6.2,  5.1, 9.0,  0, 0, 0, 0.16, 3.4, 6.0,  { tint: [1, 1, 1, 1], us: 2, vs: 1 });
  dm('box', 'lockerWall', 6.2,  5.1, 15.9, 0, 0, 0, 0.16, 3.4, 4.2,  { tint: [1, 1, 1, 1], us: 1.5, vs: 1 });
